```python
class APIHandlerBase:
    def get_data(self):
        raise NotImplementedError("Subclasses should implement this!")

    def update_data(self, data):
        raise NotImplementedError("Subclasses should implement this!")

class APIHandlerV1(APIHandlerBase):
    def get_data(self):
        return {"data": "Version 1 data"}

    def update_data(self, data):
        print(f"Updating data in version 1: {data}")

class APIHandlerV2(APIHandlerBase):
    def get_data(self):
        return {"data": "Version 2 data", "timestamp": "2023-10-05T12:00:00Z"}

    def update_data(self, data):
        print(f"Updating data in version 2: {data}")

    def delete_data(self):
        print("Data deleted in version 2")
```

